-- mod-guild-adventure: fight profile templates (GA_world). GENERATED by tools/gen_fight_templates.py from the
-- wowbot335 fight classes (profiles/fightclass/*_solo_*.json, corrected by tools/fightclass/*.patch.json) and the
-- fight classes of tools/fightclass/*.json (tanks and healers); edit those or the script, not this file. Applied
-- by the worldserver's DB updater (re-applied when the file changes); every statement is idempotent. Design:
-- docs/fight-profiles.md sections 11 and 12 (FP-4, FC5, FC12).
--
-- The same columns as the guilds' profiles (ga_fight_profile* in GA_characters): a template is a read-only fight
-- profile of no guild (ids from 1000001, kept from one generation to the next) that a bot can be given as it is or
-- that a guild copies; a bot without a profile of its own plays the template of its class, talent tree and role
-- (FC12). rule.kind 2 is a spell (the server takes the first rank of the chain), conditions are the catalogue's
-- "[!]key[:param][op value]".
DROP TABLE IF EXISTS `ga_fight_template`;
CREATE TABLE `ga_fight_template` (
    `id`           INT UNSIGNED     NOT NULL,
    `class`        TINYINT UNSIGNED NOT NULL,
    `tab`          TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'the talent tree (0-2) it is made for',
    `role`         TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '0 solo or damage, 1 a group''s tank, 2 a group''s healer',
    `name`         VARCHAR(48)      NOT NULL,
    `note`         VARCHAR(200)     NOT NULL DEFAULT '',
    `template_key` VARCHAR(128)     NOT NULL DEFAULT '' COMMENT 'where it comes from',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Guild Adventure: fight profile templates';

DROP TABLE IF EXISTS `ga_fight_template_rule`;
CREATE TABLE `ga_fight_template_rule` (
    `template_id`  INT UNSIGNED      NOT NULL,
    `list`         TINYINT UNSIGNED  NOT NULL COMMENT '0 the fight, 1 between fights (buffs)',
    `position`     SMALLINT UNSIGNED NOT NULL,
    `kind`         TINYINT UNSIGNED  NOT NULL COMMENT '2 spell',
    `ref`          INT UNSIGNED      NOT NULL DEFAULT 0 COMMENT 'spell id (any rank)',
    `target`       TINYINT UNSIGNED  NOT NULL DEFAULT 0 COMMENT '0 current target, 1 self, 2 pet, 3 the member with the least health, 4 tank, 5 an enemy that meets the conditions',
    `flags`        TINYINT UNSIGNED  NOT NULL DEFAULT 0 COMMENT '2 not twice in a row',
    `min_interval` SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'seconds',
    `relevance`    FLOAT             NOT NULL DEFAULT 0,
    `conditions`   VARCHAR(255)      NOT NULL DEFAULT '',
    `comment`      VARCHAR(64)       NOT NULL DEFAULT '' COMMENT 'the spell as the fight class names it',
    PRIMARY KEY (`template_id`, `list`, `position`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Guild Adventure: rules of a fight profile template';

DROP TABLE IF EXISTS `ga_fight_template_option`;
CREATE TABLE `ga_fight_template_option` (
    `template_id`  INT UNSIGNED     NOT NULL,
    `option_key`   VARCHAR(32)      NOT NULL,
    `label`        VARCHAR(64)      NOT NULL DEFAULT '',
    `kind`         TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '0 switch, 1 number, 2 percent',
    `value`        FLOAT            NOT NULL DEFAULT 0,
    `min_value`    FLOAT            NOT NULL DEFAULT 0,
    `max_value`    FLOAT            NOT NULL DEFAULT 100,
    PRIMARY KEY (`template_id`, `option_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Guild Adventure: options of a fight profile template';

